update public.poojas set
       why_en     = 'Sandhya means the junctures — the seams of the day where night turns to morning, morning to afternoon, afternoon to night — and this is the rite kept at each of them. It is nitya: there is no occasion and no date, which is why its resolution names no year, month, tithi or star, only which of the three sittings you are in. The centre of it is eight words, and the book says so plainly: that sun is Brahman, I am Brahman. Everything before that prepares the reciter and everything after it worships, and it is that identification which keeps the rest from being sun-worship — the water poured toward the sun, the Gayatri repeated a hundred and eight times, the sun looked at through locked fingers at noon. Each sitting also cleans the stretch of time behind it: the morning absolves the night, the evening absolves the day, and the whole rite ends by asking Savitr for children, for bad dreams to stop, and for whatever is good.',
       why_ta     = 'ஸந்தி என்பது பகலும் இரவும் சந்திக்கும் இணைப்பு வேளை — இரவு காலையாகும் இடம், காலை உச்சியாகும் இடம், உச்சி மாலையாகும் இடம். அந்த மூன்று வேளைகளிலும் செய்யப்படும் வழிபாடே இது. இது நித்யம்: இதற்குத் தனிச் சந்தர்ப்பமோ திதியோ இல்லை. அதனால்தான் இதன் ஸங்கல்பத்தில் வருடமோ மாதமோ திதியோ நட்சத்திரமோ சொல்லப்படுவதில்லை; எந்த வேளை என்பது மட்டுமே சொல்லப்படுகிறது. இதன் மையம் எட்டே சொற்கள் — அந்த சூரியனே ப்ரம்மம், நானும் ப்ரம்மமே. அதற்கு முன் உள்ளவை சொல்பவரைத் தயார்படுத்துகின்றன, அதற்குப் பின் உள்ளவை வழிபடுகின்றன. அந்த ஒன்றுபடுத்தலே மற்றவற்றைச் சூரிய வழிபாடாக மட்டும் இருக்கவிடாமல் காக்கிறது. ஒவ்வொரு வேளையும் தனக்கு முந்தைய காலத்தைச் சுத்தி செய்கிறது: காலை இரவையும், மாலை பகலையும். இறுதியில் ஸவிதாவிடம் சந்ததி, தீய கனவுகள் நீங்குதல், நன்மை ஆகியவை வேண்டப்படுகின்றன.',
       source_ref = 'Yajurveda Trikaala Sandhyaavandanam (Giri), pp.7-8',
       updated_at = now()
 where id = 'sandhyavandanam';

-- --- assert ------------------------------------------------------------------
do $$
declare n int;
begin
  select count(*) into n from public.samagri_items where pooja_id = 'sandhyavandanam';
  if n <> 10 then raise exception 'expected 10 samagri items, found %', n; end if;

  select count(*) into n from public.samagri_items
   where pooja_id = 'sandhyavandanam' and item_ta !~ '[஀-௿]';
  if n > 0 then raise exception '% samagri item(s) carry no Tamil', n; end if;

  -- Exactly two optional, and both are learning aids rather than implements.
  select count(*) into n from public.samagri_items
   where pooja_id = 'sandhyavandanam' and is_required = false;
  if n <> 2 then raise exception 'expected 2 optional items, found %', n; end if;

  -- Seq dense from 1, which the checklist relies on.
  select count(*) into n from (
    select seq, row_number() over (order by seq) as rn
      from public.samagri_items where pooja_id = 'sandhyavandanam'
  ) t where t.seq <> t.rn;
  if n > 0 then raise exception '% samagri item(s) are not numbered 1..n', n; end if;

  select count(*) into n from public.poojas
   where id = 'sandhyavandanam' and coalesce(trim(why_en), '') <> '' and coalesce(trim(why_ta), '') <> '';
  if n <> 1 then raise exception 'sandhyavandanam has no why text'; end if;

  -- Every published pooja now has one. This is the state proofread wants.
  select count(*) into n from public.poojas
   where status = 'published' and (coalesce(trim(why_en), '') = '' or coalesce(trim(why_ta), '') = '');
  if n <> 0 then raise exception '% published pooja(s) still have no why text', n; end if;

  -- No two rites share it; see 0040 for why this is checked.
  select count(distinct why_en) into n from public.poojas where why_en is not null;
  if n <> 4 then raise exception 'the why texts are not distinct: % of 4', n; end if;

  -- And it still offers no naivedyam, which is correct for this rite.
  select count(*) into n from public.naivedyam_items where pooja_id = 'sandhyavandanam';
  if n <> 0 then raise exception 'sandhyavandanam should have no naivedyam, found %', n; end if;
end $$;


